{"id": "488971e8-fb61-4d5b-922c-d53303762c19", "timestamp": "2026-10-22T17:18:50.512562", "source": "agent", "parent_id": "cf1ef83b-b91f-488f-a82a-854fe9167baa", "action": {"command": "mkdir -p /workspace/_stub && cat > /workspace/_stub/sanity_scorecard.py <<'PY'
"""
In-bubble SANITY STUB for the metrics wire-up only.
- NOT a real experiment. RDKit-less stdlib placeholders for every metric.
- Real execution uses RDKit/Morgan/Scaffold/etc. (specified in main design).
- Purpose: prove the observability surface compiles end-to-end on stdlib and
  produces a non-misleading scorecard on a 5-molecule hand-crafted fixture.
"""
import json, re, hashlib, itertools

FIXTURE = [
    "CCO",                                # ethanol (clean baseline)
    "CC(=O)Oc1ccccc1C(=O)O",              # aspirin (canonical drug-like)
    "CCCCCCCCCCCC",                       # n-dodecane (ultra-long aliphatic path = 12)
    "C1=CC=CC=C1",                        # benzene (ring system)
    "C.C.C.C",                            # disconnected fragments (period-separated)
]

# --- validity heuristic (atomic symbols from SMILES) ---
VALID_ATOMS = {"B","C","N","O","S","P","F","Cl","Br","I","H","*"}
BRACKET_RE  = re.compile(r"\[([^\]]+)\]")

def parse_smiles(s):
    # balance check
    if s.count("(") != s.count(")"): return None, "unbalanced parens"
    # bracket content sanity
    for m in BRACKET_RE.findall(s):
        if not m or m[0] not in VALID_ATOMS: return None, f"bad bracket: {m}"
    # fragment split (period-separated multi-molecule string)
    frags = s.split(".")
    return frags, None

# --- heavy-atom count ---
def heavy_atoms(s):
    n = len(BRACKET_RE.findall(s))
    s2 = BRACKET_RE.sub("", s)
    for sym in ("Cl","Br"):                     # multi-char first
        s2 = s2.replace(sym, " ")
    for sym in ("C","N","O","S","P","F","I","B"):
        n += s2.count(sym)
    return n

# --- longest CONTIGUOUS aliphatic carbon path (no ring) ---
# Very coarse stub: counts unbroken run of 'C' between ring/branch boundaries.
RING_BOND = re.compile(r"[=#:]|\d")             # bonds & ring closures break the chain
def longest_aliphatic_C_path(s):
    s = BRACKET_RE.sub("C", s)                  # collapse brackets → counted
    s = s.replace("c","C")                      # aromatic C → aliphatic-equivalent for stub
    runs, cur = [], 0
    for ch in s:
        if ch == "C" and not RING_BOND.match(ch):
            cur += 1
        else:
            if cur: runs.append(cur); cur = 0
    if cur: runs.append(cur)
    return max(runs) if runs else 0

# --- tiny in-house fingerprint: ordered char 3-grams over the canonicalised SMILES ---
def fp(s, k=3):
    s2 = re.sub(r"[^A-Za-z0-9=#()]+","", s)
    return set(s2[i:i+k] for i in range(len(s2)-k+1)) or {s2}

def tanimoto(a, b):
    return len(a & b) / max(1, len(a | b))

# --- scaffold-mock: just hash of the molecule's heavy-atom multiset (REPLACED by Bemis-Murcko) ---
def scaffold_stub(s): return hashlib.sha1(str(sorted(BRACKET_RE.findall(s))).encode()).hexdigest()[:8]

# --- composite scores ---
def property_proxy(s):
    # placeholder scalar in [0,1]: rewards moderate polarity and penalises ultra-long chains
    h = heavy_atoms(s)
    c = longest_aliphatic_C_path(s)
    return max(0.0, min(1.0, 0.6 - 0.05*max(0, c-6) + 0.05*(5 if h<25 else 0)))

def hallucination_index(s):
    # (a) ultra-long carbon path; (b) timeout-heavy atoms; (c) disconnected fragments;
    # (d) bracket-syntax flag; (e) entropy-drop placeholder via repeated-symbol run
    a = 1.0 if longest_aliphatic_C_path(s) >= 8 else 0.0
    b = 1.0 if heavy_atoms(s) > 35 else 0.0
    c = 1.0 if "." in s else 0.0
    d = 1.0 if parse_smiles(s)[1] is not None else 0.0
    e = 1.0 if re.search(r"(.)\1{6,}", s) else 0.0  # pathological repetition
    return (a + b + c + d + e) / 5.0

# --- run ---
print(f"{'SMILES':30s}  {'parse':>6s}  {'Hvy':>4s}  {'Cmax':>5s}  {'Scaf':>10s}  {'Prop':>5s}  {'Hallu':>5s}")
print("-"*80)
scores = []
for s in FIXTURE:
    frags, err = parse_smiles(s)
    h = heavy_atoms(s); c = longest_aliphatic_C_path(s)
    sc = scaffold_stub(s); p = property_proxy(s)
    hi = hallucination_index(s)
    scores.append((s, frags is not None, h, c, sc, p, hi))
    print(f"{s:30s}  {('OK' if frags is not None else 'FAIL'):>6s}  {h:>4d}  {c:>5d}  {sc:>10s}  {p:>5.2f}  {hi:>5.2f}")

# internal diversity on this fixture (illustrative; diverges from real eval set)
fps = [fp(t[0]) for t in scores]
pairs = list(itertools.combinations(range(len(fps)), 2))
div = 1.0 - (sum(tanimoto(fps[i],fps[j]) for i,j in pairs)/len(pairs))
print(f"\nillustrative internal-diversity (1-mean pairwise Tanimoto over fixture): {div:.3f}")
print("(real eval: 2048-bit Morgan radius-2 via RDKit over N=2000 generated molecules / arm -> see main design)")

# save artifact
with open("/workspace/_stub/sanity_scorecard.json","w") as f:
    json.dump({"fixture": FIXTURE,
               "rows":   [{"smiles":t[0],"parse_ok":t[1],"heavy_atoms":t[2],
                           "longest_C_path":t[3],"scaffold_stub":t[4],
                           "property_proxy":t[5],"hallucination_index":t[6]} for t in scores],
               "illustrative_internal_diversity": div}, f, indent=2)
